ze:12px;color:#8a98a8}.b2b-cabinet-list article h3{font-size:17px;margin:3px 0;color:#142338}.b2b-cabinet-list article p{margin:0;color:#617286}.b2b-cabinet-actions{display:flex;gap:7px}.b2b-cabinet-actions a,.b2b-cabinet-actions button{display:block;border:1px solid #ccd6e1;background:#fff;color:#53657a;border-radius:8px;padding:9px 12px;font-weight:700}.b2b-cabinet-actions .primary{background:#132238;color:#fff;border-color:#132238}.b2b-cabinet-order-total{text-align:right}.b2b-cabinet-order-total>*{display:block}.b2b-cabinet-order-total strong{color:#142338;white-space:nowrap}.b2b-cabinet-order-total a{color:#0b9d76;margin-top:5px}.b2b-cabinet-order-total small{color:#8a98a8}.b2b-cabinet-zero{text-align:center;padding:70px 20px;border:1px dashed #ccd6e1;border-radius:13px;color:#718196}.b2b-cabinet-zero i{font-size:42px;color:#aab7c5}.b2b-cabinet-zero h3{color:#142338;margin:12px 0 6px}.b2b-cabinet-zero a{display:inline-block;margin-top:12px;color:#0b9d76;font-weight:700}.b2b-cabinet-alert{border-radius:10px;padding:13px 16px;margin-bottom:16px}.b2b-cabinet-alert.is-success{background:#e8f8f2;color:#087453}.b2b-cabinet-alert.is-error{background:#fff0f1;color:#b62635}.b2b-reconciliation-filter{display:flex;align-items:end;gap:12px;margin-bottom:20px}.b2b-reconciliation-filter label{width:190px}.b2b-reconciliation-filter button{margin:0}.b2b-reconciliation-filter button:last-child{background:#fff;color:#132238;border:1px solid #ccd6e1}.b2b-reconciliation-sheet{border:1px solid #ccd6e1;padding:30px;border-radius:12px}.b2b-reconciliation-sheet header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #142338;padding-bottom:15px;margin-bottom:20px}.b2b-reconciliation-sheet header div{text-align:right}.b2b-reconciliation-sheet header span,.b2b-reconciliation-sheet header strong{display:block}.b2b-reconciliation-sheet header strong{font-size:20px;color:#142338}.b2b-reconciliation-sheet table{width:100%;border-collapse:collapse;margin:2